proguardAdditions.insert:
-dontwarn com.Plugins.**
-keep class com.Plugins.** { *; }
-keep interface com.Plugins.** { *; }
-keep public class com.Plugins.AndroidNative.** { public protected *; }

-dontwarn androidx.**
-keep class androidx.** { *; }
-keep interface androidx.** { *; }

buildGradleAdditions.insert:
ext {
    android {
        buildTypes {
            release {
                minifyEnabled false
            }
        }
    }
}

repositories {
  mavenCentral()
  google()
}


dependencies {
  implementation 'com.google.guava:guava:28.2-android'
}

baseBuildGradleAdditions.insert:
allprojects {
  def mappings = [
    'android.support.annotation': 'androidx.annotation',
    'android.arch.lifecycle': 'androidx.lifecycle',
    'android.support.v4.app.NotificationCompat': 'androidx.core.app.NotificationCompat',
    'android.support.v4.app.ActivityCompat': 'androidx.core.app.ActivityCompat',
    'android.support.v4.content.ContextCompat': 'androidx.core.content.ContextCompat',
    'android.support.v4.app.NotificationManagerCompat': 'androidx.core.app.NotificationManagerCompat',
    'android.support.v4.content.FileProvider': 'androidx.core.content.FileProvider',
    'android.support.v13.app.FragmentCompat': 'androidx.legacy.app.FragmentCompat',
    'android.arch.lifecycle.Lifecycle': 'androidx.lifecycle.Lifecycle',
    'android.arch.lifecycle.LifecycleObserver': 'androidx.lifecycle.LifecycleObserver',
    'android.arch.lifecycle.OnLifecycleEvent': 'androidx.lifecycle.OnLifecycleEvent',
    'android.arch.lifecycle.ProcessLifecycleOwner': 'androidx.lifecycle.ProcessLifecycleOwner',
  ]

beforeEvaluate { project ->
  project.rootProject.projectDir.traverse(type: groovy.io.FileType.FILES, nameFilter: ~/.*\.java$/) { f ->
      mappings.each { entry ->
        if (f.getText('UTF-8').contains(entry.key)) {
          println "Updating ${entry.key} to ${entry.value} in file ${f}"
          ant.replace(file: f, token: entry.key, value: entry.value)
        }
      }
    }
  }
}

gameActivityImportAdditions.insert:
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import android.content.pm.PackageManager;

gameActivityClassAdditions.insert:
// Implemented natively in AndroidNativePermissions.cpp
public native void nativeAndroidNativeOnPermissionResult(String[] permissions, boolean[] granted);

public void AndroidNative_RequestPermissions(final String[] permissions) {
  try {
    java.util.ArrayList<String> toRequest = new java.util.ArrayList<String>();
    for (String p : permissions) {
      if (ContextCompat.checkSelfPermission(this, p) != PackageManager.PERMISSION_GRANTED) {
        toRequest.add(p);
      }
    }

    if (toRequest.isEmpty()) {
      boolean[] granted = new boolean[permissions.length];
      for (int i = 0; i < permissions.length; i++) { granted[i] = true; }
      nativeAndroidNativeOnPermissionResult(permissions, granted);
      return;
    }

    ActivityCompat.requestPermissions(this, toRequest.toArray(new String[0]), 11011);
  } catch (Exception e) {
    boolean[] granted = new boolean[permissions.length];
    nativeAndroidNativeOnPermissionResult(permissions, granted);
  }
}

gameActivityOnRequestPermissionsResultAd.insert:
if (requestCode == 11011) {
  boolean[] granted = new boolean[grantResults.length];
  for (int i = 0; i < grantResults.length; i++) {
    granted[i] = (grantResults[i] == PackageManager.PERMISSION_GRANTED);
  }
  nativeAndroidNativeOnPermissionResult(permissions, granted);
}
